  ('de-ziaglbeem', 'de Ziaglbeem', '', '', '', '', 'die Ziegelböhmen', '[{"kategorie": "", "text": "zugewanderte Ziegelarbeiter aus Böhmen"}, {"kategorie": "", "text": "Fremdarbeiter für die Ziegeleien im Süden Wiens ([[Wienerberg]]), die im 19. Jahrhundert überwiegend aus Böhmen und Mähren zugewandert waren"}]'::jsonb, ''),
  ('beemischa-prooda', 'Beemischa Prooda', '', '', '', '', 'Böhmischer Prater', '[{"kategorie": "wörtlich", "text": "\"Vergnügungspark im [[Laaer]] Wald im 10. Wiener Gemeindebezirk (Favoriten)\" (vom lateinischen \"pratum\"=\"Wiesengrund\")"}, {"kategorie": "hist.", "text": "Seit der zweiten Hälfte des 19. Jahrhunderts war der Laaer Wald eines der beliebtesten Ausflugsziel und von Favoriten aus in ca. 15 Minuten zu Fuß zu erreichen. Franz Bauer, ein Kantinenwirt des Ziegelwerks [[Laaer]] Wald, führte hier eine kleine Gastwirtschaft , die sich bald zu einem beliebten Zielpunkt für Sonntagsausflüge der sogenannten \"Ziegelböhm\", der hauptsächlich aus Böhmen und Mähren stammenden Arbeiter der Wiener Ziegelwerke entwickelte. 1882 suchte Franz Bauer um die Erlaubnis an, neben seinem Gasthaus auch \"Spiele\" veranstalten zu dürfen und stellte zu diesem Zweck eine Schaukel und ein Ringelspiel auf. 1884 hatten sich im Laaer Wald bereits 20 Gaststätten und zahlreiche Schausteller angesiedelt, die den Grundstock \"des kleinen Praters\" bildeten, welcher aufgrund seiner Besucher schon bald den Namen \"BÖHMISCHER PRATER\" erhielt. Der \"Böhmische Prater\" ist bis heute ein beliebter Vergnügungsort der Wiener mit zahlreichen Fahrgeschäften und Gaststätten."}]'::jsonb, ''),
  ('beemischa-zirkl', 'beemischa Zirkl', '', '', '', '', 'böhmischer Zirkel', '[{"kategorie": "", "text": "böhmischer Diebesgriff (der rechte Daumen ist der Zirkelschenkel, und die vier Finger formen einen Kreis)"}, {"kategorie": "", "text": "Diebstahl, Klau"}]'::jsonb, ''),
  ('an-beemischn-zirkl-mochn', 'an beemischn Zirkl mochn', '', '', '', '', 'einen böhmischen Zirkel machen', '[{"kategorie": "", "text": "\"lange Finger machen\""}, {"kategorie": "", "text": "stehlen, klauen, [[fladern]], [[schnipfen]]"}]'::jsonb, ''),
  ('beemisch-einkaufn-gehen', 'beemisch einkaufn gehen', '', '', '', '', 'böhmisch einkaufen gehen', '[{"kategorie": "", "text": "stehlen, klauen"}, {"kategorie": "", "text": "[[fladern]], [[schnipfen]], [[grapschen]]"}]'::jsonb, ''),
  ('beemischa-foeoela', 'beemischa Fööla', '', '', '', '', 'ein böhmischer Fehler', '[{"kategorie": "", "text": "Zahlendreher, Ziffernsturz, Ziffernumkehr"}, {"kategorie": "", "text": "Vertauschung der Ziffern einer Zahl (Der Ausdruck kommt daher, dass die Böhmen (so wie auch fast alle anderen slawischen Völker) die Wörter für zweistellige Zahlen in der Reihenfolge bilden, wie die Ziffern auch auf dem Papier stehen (d.h. zunächst die Zehnerstelle und dann die Einerstelle), und nicht \"anders herum\" wie im Deutschen, z.B. \"82\" statt richtigerweise \"28\"."}]'::jsonb, ''),
  ('beemische-fotzn', 'beemische Fotzn', '', '', '', 'Wiener Gaunersprache', 'böhmische Fotze', '[{"kategorie": "wörtlich", "text": "\"eine böhmische Watschen\""}, {"kategorie": "scherzhaft für", "text": "\"eine Ohrfeige mit dem Handrücken\", Handrückenschlag, Handrückenschelle, Handrücken-Kinnlader, [[Verkehrte]], [[Aawiche]]"}]'::jsonb, 'Mit aana aanzign beemischn Fotzn hodan aufdread ghaud!'),
