  ('dea-schaud-aus-wiara-bojazzo', 'Dea schaud aus wiara Bojazzo!', '', '', '', '', 'Der schaut aus wie ein Bajazzo!', '[{"kategorie": "", "text": "Der schaut aus wie ein Kasperl!  2. Der sieht aus wie eine [[Witzfigur]]!"}]'::jsonb, ''),
  ('mia-geed-da-oasch-auf-grundeis', 'Mia geed da Oasch auf Grundeis!', '', '', '', '', 'Mir geht der Arsch auf Grundeis!', '[{"kategorie": "", "text": "Mir wird angst und bange!  2. Ich mach in die Hose vor Angst!"}]'::jsonb, ''),
