  ('bremassln', 'Bremassln', '', '', '', '', 'Bremasseln', '[{"kategorie": "", "text": "Kribbeln,  2. kribbeliges Gefühl (auf der Haut bzw. bei eingeschlafenen Gliedmaßen, als wäre man mit Brennesseln in Berührung gekommen)"}]'::jsonb, ''),
