  ('hoid-in-broodloodn-du-funsn', 'Hoid in Broodloodn, du Funsn!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Halte deinen Brotladen, du Funsen!', '[{"kategorie": "wörtlich", "text": "\"Halt den Mund, du eingebildetes Frauenzimmer!\"  2. Halt''s Maul, du dumme, eingebildete Gans!  3. [[Sei]] schdaad, du [[Zääzn]]!"}]'::jsonb, ''),
  ('heast-moch-dein-broodloodn-zua', 'Heast, moch dein Broodloodn zua!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Hey, mach deinen Brotladen zu!', '[{"kategorie": "wörtlich", "text": "\"Mach deinen Mund zu!\" (scherzhafte Aufforderung an jemanden, der beim Gähnen den Mund weit aufreißt oder mit offenem Mund gedankenverloren herumsteht)"}, {"kategorie": "", "text": "Mach die Klappe zu, da zieht''s!  3. Mach die Klappe zu, bevor dir noch ein Vogel reinfliegt!"}]'::jsonb, ''),
  ('sei-schdaad-du-zaeaezn', 'Sei schdaad, du Zääzn!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Sei stad, du Zäzen!', '[{"kategorie": "wörtlich", "text": "\"Halt den Mund, du überempfindliches Frauenzimmer!\"  2. Halt''s Maul, du wehleidiges Sensibelchen!  3. [[Hoid]] in Broodloodn, du Funsn!"}]'::jsonb, ''),
  ('dea-hockt-auf-seine-tschick-wiara-bruadhenn', 'Dea hockt auf seine Tschick wiara Bruadhenn!', '', '', '', 'Echte Wiener Schmähperlen', 'Er sitzt auf seinen Tschick wie eine Bruthenne!', '[{"kategorie": "", "text": "Er hütet seine Zigaretten wie eine Bruthenne"}, {"kategorie": "", "text": "Er sitzt wie ein Geizhals auf seinen Zigaretten!   3. Der bewacht seine Zigaretten wie ein Pitbull seinen Knochen!"}]'::jsonb, ''),
