  ('krump-und-buuglad', 'krump und buuglad', '', '', '', '', 'krump und bucklert', '[{"kategorie": "wörtlich", "text": "\"krumm und bucklig\" (vom mittelhochdeutschen \"krump\"=\"krumm\" und \"bucklert\"=\"bucklig\")"}, {"kategorie": "allg.", "text": "gekrümmt und höckrig"}]'::jsonb, 'si krump und buuglad lochn'),
