  ('kvosdek-dreiick', 'Kvosdek-Dreiick', '', '', '', '', 'Chvostek-Dreieck', '[{"kategorie": "wörtlich", "text": "\"dreieckige Öffnung knapp oberhalb des Hosenbunds, welche Einblicke auf die Unterwäsche und die Haut ihres Trägers freigibt, weil dieser sein Hemd nicht oder bloß höchst schlampig zugeknöpft hat\" (in Anspielung auf den österreichischen Arzt Franz Chvostek)"}, {"kategorie": "scherzhaft für", "text": "\"schlampig zugeknöpfte Hemdfront bzw. Hosenschlitzöffnung\""}]'::jsonb, ''),
