  ('kottaedsch-viartl', 'Kottädsch-Viartl', '', '', '', '', 'Cottageviertel', '[{"kategorie": "", "text": "Nobelviertel, Villenviertel, elitäres Wiener Stadtviertel (insbesondere in den Wiener Stadtbezirken Döbling, Währing und Hietzing)"}, {"kategorie": "hist.", "text": "Das Cottageviertel wurde ab den 1870er Jahren als Gartenstadt geplant und von der Cottage Baugesellschaft entwickelt. Die Idee war, eine Wohngegend zu schaffen, die sich durch große Grundstücke und villenartige Bauten auszeichnet, die in einer naturnahen Umgebung stehen. Die [[Cottagegasse]] ist eine der prägenden Straßen dieses Viertels und spiegelt den Charme und das gehobene Wohngefühl des Cottageviertels wider."}]'::jsonb, ''),
  ('ane-aufs-doch-kriang', 'ane aufs Doch kriang', '', '', '', '', 'eine aufs Dach kriegen', '[{"kategorie": "", "text": "einen Rüffel bekommen"}, {"kategorie": "", "text": "einen Anschiss bekommen"}]'::jsonb, ''),
  ('dafia-schdee', 'dafia schdee', '', '', '', '', 'dafür stehen', '[{"kategorie": "", "text": "sich lohnen"}, {"kategorie": "", "text": "sich auszahlen, sich bezahlt machen"}]'::jsonb, ''),
  ('des-schdeed-ned-dafia', 'Des schdeed ned dafia!', '', '', '', '', 'Das steht nicht dafür!', '[{"kategorie": "", "text": "Das zahlt sich nicht aus!  2. Das lohnt sich nicht!"}]'::jsonb, ''),
  ('beehmische-doikn-mit-powidfl-und-raam', 'beehmische Doikn mit Powidfl und Raam', '', '', '', '', 'böhmische Dalken mit Powidl und Rahm', '[{"kategorie": "wörtlich", "text": "\"böhmische Dalken mit Zwetschkenmarmelade [Pflaumenkonfitüre] und Sahne\" (von [[Dalk]]=\"teigige Masse\")"}, {"kategorie": "", "text": "Mehlspeise aus [[Germteig]] (kleine, runde, in Schweineschmalz ausgebackene und mit Pflaumenkonfitüre gefüllte Teigfladen)"}]'::jsonb, ''),
  ('aum-daumpfa-foan', 'aum Daumpfa foan', '', '', '', '', 'am Dampfer fahren', '[{"kategorie": "", "text": "auf der Pechstraße fahren, das Pech an den Fersen haben"}, {"kategorie": "", "text": "vom Glück verlassen sein"}]'::jsonb, ''),
  ('du-bist-aum-foischn-daumpfa', 'Du bist aum foischn Daumpfa!', '', '', '', '', 'Du bist auf dem falschen Dampfer!', '[{"kategorie": "", "text": "Du irrst dich!  2. Du bist auf dem Holzweg!"}]'::jsonb, ''),
  ('gruena-heinrich', 'Grüna Heinrich', '', '', '', '', 'Grüner Heinrich', '[{"kategorie": "Gaunersprache, scherzhaft für", "text": "Arrestantenwagen, Gefangenentransporter, [[Frosch]] (in Anspielung auf dessen einstmals grüne Farbe)"}, {"kategorie": "Deutschland", "text": "\"Grüne Minna\", Grüner August\""}]'::jsonb, ''),
  ('des-mochds-kraut-aa-ned-fett', 'Des mochds Kraut aa ned fett!', '', '', '', '', 'Das macht das Kraut auch nicht fett!', '[{"kategorie": "idiom.", "text": "\"Das macht nicht wirklich einen großen Unterschied!\"  2. Das bringt uns nicht wirklich viel!  3. Das ist auch nur ein Tropfen auf den heißen Stein!"}]'::jsonb, ''),
  ('dea-is-heit-total-daneem', 'Dea is heit total daneem!', '', '', '', '', 'Der ist heute total daneben!', '[{"kategorie": "wörtlich", "text": "\"Der ist heute völlig neben der Spur!\"  2. Der ist heute völlig von der Rolle!  3. Der ist heute komplett weggetreten!"}]'::jsonb, ''),
  ('ea-hot-daneem-gschossn', 'Ea hot daneem gschossn!', '', '', '', '', 'Er hat daneben geschossen!', '[{"kategorie": "wörtlich, Fußballerjargon", "text": "\"Er hat vorbeigeschossen!\"  2. Er hat das Tor verfehlt!  3. Er hat das Goal nicht getroffen!"}]'::jsonb, ''),
  ('de-wuatmoeoedung-woa-daneem', 'De Wuatmöödung woa daneem!', '', '', '', '', 'Die Wortmeldung war daneben!', '[{"kategorie": "wörtlich", "text": "\"Die Wortmeldung war unangebracht!\"  2. Dieser Kommentar war fehl am Platze!  3. Diese Bemerkung war unangemessen!"}]'::jsonb, ''),
  ('ea-hod-daquea-eiparkt', 'Ea hod daquea eiparkt!', '', '', '', '', 'Er hat derquer eingeparkt!', '[{"kategorie": "wörtlich", "text": "\"Er hat der Quere nach eingeparkt\""}, {"kategorie": "", "text": "Er hat in Querrichtung eingeparkt!  Er hat den Schrägparkplatz genommen!"}]'::jsonb, ''),
  ('dea-is-ma-daquea-kumma', 'Dea is ma daquea kumma!', '', '', '', '', 'Der ist mir derquer gekommen!', '[{"kategorie": "wörtlich", "text": "\"Der ist mir in die Quere gekommen!\"  2. (fig.) Der ist mir ins Gehege gekommen!  3. (Fußballerjargon): Der ist mir mitten zwischen die Beine gelaufen!  4. Der ist mir direkt in die Parade gegrätscht!"}]'::jsonb, ''),
  ('dea-schaut-owa-daasich-drei', 'Dea schaut owa daasich drei!', '', '', '', '', 'Der schaut aber dasig drein!', '[{"kategorie": "wörtlich", "text": "\"Der schaut aber verschlafen drein!\"  2. Der sieht ganz schön benommen aus!  3. Der guckt aber teilnahmslos aus der Wäsche!  4. Der schaut drein, als wäre er völlig weggetreten!"}]'::jsonb, ''),
  ('sii-hod-an-doosign-gheirat', 'Sii hod an Doosign gheirat!', '', '', '', '', 'Sie hat einen Dasigen geheiratet', '[{"kategorie": "wörtlich", "text": "\"Sie hat einen ''von da'' geheiratet\""}, {"kategorie": "", "text": "Sie hat einen Ortsansässigen geheiratet!  3. Sie hat einen ''Hiesigen'' geheiratet! (soehe auch [[Dasiger]])"}]'::jsonb, ''),
  ('kumm-daune', 'Kumm daune!', '', '', '', '', 'Komm daune!', '[{"kategorie": "wörtlich", "text": "\"Komm runter!\"  2. Komm die Treppe runter!  3. Begib dich nach unten!"}]'::jsonb, ''),
  ('hau-d-hockn-daune', 'Hau d''Hockn daune!', '', '', '', '', 'Hau die Hacken daune!', '[{"kategorie": "wörtlich", "text": "\"Schmeiß die Arbeit hin!\"  2. Lass den Job sausen!  3. Gib die Arbeit auf!  4. Pfeif auf die Arbeit und kündige!"}]'::jsonb, ''),
  ('toni-gee-daune', 'Toni, gee daune!', '', '', '', '', 'Toni, geh daune!', '[{"kategorie": "wörtlich", "text": "\"Toni, geh von dannen!\"  2. (scherzhaft für): \"Toni, [[draa]] di!\"  3. Toni, tritt zur Seite!"}]'::jsonb, ''),
  ('daune-haun', 'daune haun', '', '', '', '', 'daunehauen', '[{"kategorie": "wörtlich", "text": "\"von dannen hauen\" (aus dem Adverb [[daune]]=\"hinweg\" und dem Verb [[hauen]]=\"werfen\")"}, {"kategorie": "allg.", "text": "wegwerfen, wegschmeißen, entsorgen"}, {"kategorie": "fig.", "text": "etwas aufgeben, sausen lassen, hinschmeißen"}]'::jsonb, 'Hau d''Hockn daune!'),
  ('den-hiinnichn-lusta-kaunnst-daune-haun', 'Den hiinnichn Lusta kaunnst daune haun!', '', '', '', '', 'Den kaputten Luster kannst du wegschmeißen!', '[{"kategorie": "wörtlich", "text": "\"Den kaputten Deckenleuchter kannst du wegwerfen!\"  2. Den defekten Mehrarmleuchter kannst du entsorgen!  3. Den Deckenleuchter kannst du in den Müll tun, der ist kaputt!"}]'::jsonb, 'daune haun'),
  ('dea-ziagd-davoo-wiara-blitz', 'Dea ziagd davoo wiara Blitz!', '', '', '', '', 'Der zieht davon wie ein Blitz!', '[{"kategorie": "scherzhaft für", "text": "\"Der schießt los wie ein Pfeil!\"  2. Der lässt alle stehen!  3. Der setzt sich in Lichtgeschwindigkeit ab!"}]'::jsonb, ''),
  ('schau-dazua-dassd-a-hockn-kriagst', 'Schau dazua, dassd a Hockn kriagst!', '', '', '', '', 'Schau dazu, dass du eine Hacken kriegst!', '[{"kategorie": "wörtlich", "text": "\"Sieh zu, dass du Arbeit findest!\"  2. Streng dich an, einen Job zu bekommen!  3. Sorg dafür, dass du bald eine Stelle hast!"}]'::jsonb, 'Schau dazua!'),
  ('schau-dazua', 'Schau dazua!', '', '', '', '', 'Schau dazu!', '[{"kategorie": "wörtlich", "text": "\"Kümmere dich drum!\"  2. Gib dir Mühe!  3. Streng dich an!  4. Leg dich ins Zeug!  5. Beeil dich!  6. Mach hin!"}]'::jsonb, ''),
  ('wem-ane-aum-deckl-geem', 'wem ane aum Deckl geem', '', '', '', '', 'jemandem eins auf den Deckel geben', '[{"kategorie": "wörtlich", "text": "\"jemandem eins auf die Mütze geben\""}, {"kategorie": "", "text": "jemandem einen Rüffel erteilen"}, {"kategorie": "", "text": "\"jemandem eins drüberziehen\""}]'::jsonb, ''),
  ('ane-aum-deckl-kriang', 'ane aum Deckl kriang', '', '', '', '', 'eins auf den Deckel kriegen', '[{"kategorie": "wörtlich", "text": "\"eins auf die Mütze bekommen\""}, {"kategorie": "", "text": "einen Anschiss bekommen"}, {"kategorie": "", "text": "einen Verweis bekommen"}, {"kategorie": "", "text": "\"eins drüberkriegen\""}]'::jsonb, ''),
  ('wem-ane-aum-deckl-haun', 'wem ane aum Deckl haun', '', '', '', '', 'jemandem eins auf den Deckel hauen', '[{"kategorie": "wörtlich", "text": "\"jemandem eins auf die Mütze geben\""}, {"kategorie": "", "text": "jemandem einen Schlag auf den Kopf verpassen"}, {"kategorie": "", "text": "\"jemandem eins drüberziehen\""}]'::jsonb, ''),
  ('i-soogs-in-voodan', 'I soogs in Voodan!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Ich sag''s dem Vater!', '[{"kategorie": "wörtlich", "text": "\"Ich werd''s dem Vater sagen!\" 2. Ich werde dem Alten Bescheid geben!  3. Das werd'' ich dem Vater berichten!"}]'::jsonb, ''),
  ('i-ruaf-in-voodan', 'I ruaf in Voodan!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Ich rufe den Vater!', '[{"kategorie": "wörtlich", "text": "\"Ich werde den Vater rufen!\"  2. Ich werde den Vater zu Hilfe holen!  3. Ich werde den Alten verständigen!"}]'::jsonb, ''),
  ('bin-in-aumt', 'Bin in Aumt!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Bin in Amt!', '[{"kategorie": "wörtlich", "text": "\"Bin im Amt!  2. \"Bin im Dienst!\"  3. \"Bin im Einsatz!\""}]'::jsonb, ''),
  ('aane-is-ma-ned-gnua', 'Aane is ma ned gnua!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Eine ist mir nicht genug!', '[{"kategorie": "wörtlich", "text": "\"Eine allein genügt mir nicht!\"  2. \"Mit einer gebe ich mich nicht zufrieden!\"  3. \"Eine allein macht mich nicht satt!\""}]'::jsonb, ''),
  ('drei-san-kumma-owa-nuar-aane-is-bliebm', 'Drei san kumma, owa nuar aane is bliebm!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Drei sind gekommen, aber nur eine ist geblieben!', '[{"kategorie": "wörtlich", "text": "\"Es sind drei gekommen, aber nur eine ist geblieben!\"  2. Von den drei Gekommenen ist nur eine geblieben!  3. Sie kamen zu dritt - aber am Ende ist nur eine von ihnen geblieben!"}]'::jsonb, ''),
  ('drei-san-kumma-owa-nuar-aana-is-bliebm', 'Drei san kumma, owa nuar aana is bliebm!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Drei sind gekommen, aber nur einer ist geblieben!', '[{"kategorie": "wörtlich", "text": "\"Es sind drei gekommen, aber nur einer ist geblieben!\"  2. Von den drei Gekommenen ist nur einer geblieben!  3. Sie kamen zu dritt - aber am Ende ist nur einer von ihnen geblieben!"}]'::jsonb, ''),
  ('drei-san-kumma-owa-nuar-aana-hoda-wos-geebm', 'Drei san kumma, owa nuar aana hoda wos geebm!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Drei sind gekommen, aber nur einer hat er was gegeben!', '[{"kategorie": "wörtlich", "text": "\"Drei kamen, aber nur einer gab er etwas!\"  2. Von den dreien, die gekommen waren, hat er nur einer was geschenkt!  3. Obwohl sie zu dritt waren, überreichte er nur einer ein Geschenk!"}]'::jsonb, ''),
  ('med-aana-schwoazn-dintn', 'Med aana schwoazn Dintn!', '', '', '', 'Wienerisches aus Musik, Kunst, Kultur & Medien', 'Mit einer schwarzen Tinte!', '[{"kategorie": "wörtlich, Buchtitel", "text": "\"Mit ''ner schwarzen Tinte!\" (Titel eines Gedichtbands im Wiener Dialekt vom H. C. Artmann)"}, {"kategorie": "vollständiger Titel", "text": "\"Mit einer schwarzen Tinte - Gedichte aus Breitensee\""}, {"kategorie": "hist.", "text": "H. C. Artmann (1921-2000) war ein sprachverspielter österreichischer Dichter der Wiener Gruppe. Sein berühmter Gedichtband „Med ana schwoazzn Dintn“ (1958) ist ein literarisches Meisterwerk in Wiener Dialekt, das mit düsteren Bildern, schwarzem Humor und poetischer Sprachkunst Dialektlyrik revolutionierte"}]'::jsonb, ''),
  ('i-waass-du-hosd-jetzd-aan-freind-mid-aan-poasche-soog-eam-ea-soi-in-oasch-gee', 'I waass, du hosd jetzd aan Freind mid aan Poasche - soog eam, ea soi in Oasch gee!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Ich weiß, du hast jetzt einen Freund mit einem Porsche - sag ihm, er soll in Arsch gehen!', '[{"kategorie": "wörtlich", "text": "\"Ich weiß, du hast jetzt einen Freund mit einem Porsche - sag ihm, er soll in Arsch gehen!\" (Textzeile aus Georg Danzers Song ''Ruaf mi ned au!'')"}, {"kategorie": "", "text": "Gratuliere dir zum Neuen mit dem Porsche – richte ihm aus: er soll in Arsch gehen!   3. Jaja, dein Porsche-Hengst – weißt du was, der kann mich am Arsch lecken!"}]'::jsonb, ''),
  ('a-bua-und-a-maadl-foan-im-zeislwoong-auf-a-laundpartii', 'A Bua und a Maadl foan im Zeislwoong auf a Laundpartii!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Ein Bub und ein Mädchen fahren im Zeiselwagen auf ''ne Landpartie!', '[{"kategorie": "wörtlich", "text": "\"Ein Bub und ein Mädchen machen mit ''ner Ausflugskutsche eine Landpartie!\"  2. Ein Junge und ein Mädchen unternehmen einen Ausflug mit der Kutsche aufs Land!  3. Zwei junge Seelen fahren im Pferdewagen ins Grüne hinaus!"}]'::jsonb, ''),
  ('so-a-drei-oda-viire-kunntasd-ma-schoo-mitgeebm', 'So a drei oda viire kunntasd ma schoo mitgeebm!', '', '', '', 'Wiener Sprüche, die sitzen!', 'So drei oder vier könntest du mir schon mitgeben!', '[{"kategorie": "wörtlich", "text": "\"So circa drei oder vier kannst du mir gerne mitgeben!\"  2. So um die drei oder vier würde ich durchaus mitnehmen wollen!  3. Ungefähr drei oder vier tät'' ich mir gerne unter den Nagel reißen!"}]'::jsonb, ''),
  ('a-so-wos', 'A so wos!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Ach so was!', '[{"kategorie": "wörtlich", "text": "\"Also so was!\"  2. \"Ist das die Möglichkeit?\"  3. Na so was!  4. Kann das wahr sein?"}]'::jsonb, ''),
  ('i-kunntad-schoo-noo-a-bia-vatroong', 'I kunntad schoo noo a Bia vatroong!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Ich könnte schon noch ein Bier vertragen!', '[{"kategorie": "wörtlich", "text": "\"Ich hätte durchaus noch Platz für ein Bier!\"  2. Ich könnte schon noch ein Bier gebrauchen!  3. Noch ein Bier würde mir jetzt richtig gut tun!"}]'::jsonb, ''),
  ('kunntad-ma-des-ned-aafoch-moi-ausprobian', 'Kunntad ma des ned aafoch moi ausprobian?', '', '', '', 'Wiener Sprüche, die sitzen!', 'Könnte man das nicht einfach mal ausprobieren?', '[{"kategorie": "wörtlich", "text": "\"Lasst uns das doch einfach mal ausprobieren!\"  2. Vielleicht könnte man es einfach mal versuchen?  3. Könnte man nicht wenigstens mal einen Testlauf machen?"}]'::jsonb, ''),
  ('du-kunntadsd-des-schoo-mochn-waunnsd-di-zsaummreissd', 'Du kunntadsd des schoo mochn, waunnsd di zsaummreissd!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Du könntest das schon machen, wenn du dich zusammenreißt!', '[{"kategorie": "wörtlich", "text": "\"Du könntest das locker machen – du musst dich nur anstrengen!\"  2. Du wärst dazu durchaus in der Lage, wenn du dich bemühst!  3. Du könntest das locker hinkriegen, wenn du dich nicht so gehen ließest!"}]'::jsonb, ''),
  ('kunntads-ees-oda-hobds-z-tuan', 'Kunntads ees oda hobds z''tuan?', '', '', '', 'Wiener Sprüche, die sitzen!', 'Könntet ihr oder habt ihr zu tun?', '[{"kategorie": "wörtlich", "text": "\"Hättet ihr Zeit oder seid ihr beschäftigt?\"  2. Könnt ihr vielleicht oder seid ihr anderweitig unterwegs?  3. Könnt ihr vorbeikommen oder seid ihr verhindert?"}]'::jsonb, ''),
  ('mia-kunntadn-heit-amoi-olle-soatn-bia-duachkostn-alfabeetisch', 'Mia kunntadn heit amoi olle Soatn Bia duachkostn - alfabeetisch!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Wir könnten heute mal alle Sorten Bier durchkosten - alphabetisch!', '[{"kategorie": "wörtlich", "text": "\"Wir könnten uns heute mal alphabetisch durchs Bierangebot saufen!\"  2. Wir könnten uns heute durch die komplette Bierkarte trinken,  und zwar alphabetisch: von A wie Amstel bis Z wie Zipfer!  3. Heut saufen wir uns das ganze Alphabet runter – von A wie Amstel bis Z wie Zipfer!"}]'::jsonb, ''),
  ('heans-kunntadn-s-ma-dees-bitte-nochschaun', 'Heans, kunntadn''S ma dees bitte nochschaun?', '', '', '', 'Wiener Sprüche, die sitzen!', 'Hören Sie, könnten Sie mir das bitte nachschauen?', '[{"kategorie": "wörtlich", "text": "\"Wären Sie so freundlich, das für mich nachzuschauen?\"  2. Dürfte ich Sie bitten, das für mich nachzusehen?  3. Haben Sie vielleicht kurz Zeit, das für mich nachzusehen?"}]'::jsonb, ''),
  ('du-bist-aa-a-dillo', 'Du bist aa a Dillo!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Du bist aber auch ein Dillo!', '[{"kategorie": "wörtlich", "text": "\"Du bist wirklich ''ne Dumpfbacke!\"  2. (fig.) Du bist echt ein Schwachkopf!  3. Du bist wahrhaftig ein Depp!"}]'::jsonb, ''),
  ('i-brauchad-eia-haums-aa', 'I brauchad Eia, haums aa?', '', '', '', 'Wiener Sprüche, die sitzen!', 'Ich bräuchte Eier, haben Sie welche?', '[{"kategorie": "wörtlich", "text": "\"Ich hätte gerne Eier, haben Sie noch welche?\"  2. Ich benötige Eier, hätten Sie welche vorrätig?  3. Ich hätte gerne Eier, haben Sie noch welche da?"}]'::jsonb, ''),
  ('do-brauchsd-nua-aans-und-aans-zsaummzoeoen', 'Do brauchsd nua aans und aans zsaummzöön!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Da brauchst du nur eins und eins zusammenzählen!', '[{"kategorie": "wörtlich", "text": "\"Das liegt doch auf der Hand!\"  2. Da kommt man auch mit gesundem Menschenverstand drauf!  3. Das kann man sich doch leicht ausrechnen!"}]'::jsonb, ''),
  ('auf-meina-ua-is-aans', 'Auf meina Ua is aans!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Auf meiner Uhr ist es eins!', '[{"kategorie": "wörtlich", "text": "\"Bei mir ist es ein Uhr!\"  2. Es ist ein Uhr früh nach meiner Zeit!  3. Der Zeiger steht bei mir auf dreizehn Uhr!  4. Bei mir ist es ein Uhr nachmittags!"}]'::jsonb, ''),
  ('mia-is-ollas-aans-ob-i-a-goeoed-hob-oda-kaans', 'Mia is ollas aans - ob I a Gööd hob oda kaans!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Mir ist alles eins - ob ich ein Geld hab oder keins!', '[{"kategorie": "wörtlich, Titel eines bekannten Wienerlieds", "text": "\"Mir ist alles einerlei - ob ich ein Geld hab oder keins!  2. \"Mir doch wurscht, ob Geld im Schrank – ich bleib locker, ehrlich, frank!\"  3. \"Ob reich oder arm - mir ist alles [[blunzen]]!\""}]'::jsonb, ''),
  ('da-haeaefnfrooss-is-zum-schbeibm-owa-im-bau-aachlsd-ollas', 'Da Hääfnfrooss is zum Schbeibm - owa im Bau aachlsd ollas!', '', '', '', 'Wiener Gaunersprache', 'Der Häfenfraß ist zum Speiben - aber im Bau achelst du alles!', '[{"kategorie": "wörtlich", "text": "\"Der Knastfraß ist zum Kotzen - aber im Bau futterst du alles!\"  2. Die Anstaltsküche ist ''ne Zumutung – aber im Bau schiebst du dir alles rein!  3. Das Essen aus der Knastkantine schmeckt wie Brechmittel – aber wer im Bau ist, löffelt trotzdem!"}]'::jsonb, ''),
  ('aachlputz-dreimoi-aum-toog-des-is-ned-essn-des-is-haeaefnschdroof-mit-beschdeck', 'Aachlputz dreimoi aum Toog - des is ned essn, des is Hääfnschdroof mit Beschdeck!', '', '', '', 'Wiener Gaunersprache', 'Achelputz dreimal am Tag - das ist nicht essen, das ist Häfenstrafe mit Besteck!', '[{"kategorie": "wörtlich", "text": "\"Knastfraß dreimal täglich – das ist nicht essen, das ist Strafe mit Besteck!\"  2. Zellenfraß zum Frühstück, Mittag und Abend – das ist nicht essen, das ist Bestrafung in kleinen Portionen!  3. Dreimal täglich Löffelpflicht – das ist nicht füttern, das ist Strafvollzug zum Schlucken!"}]'::jsonb, ''),
  ('daedst-ma-an-tschik-wuuzln-es-geed-jo-nix-iwa-a-soeoewagwuuzlde-goeoe', 'Dädst ma an Tschik wuuzln? - Es geed jo nix iwa a Sööwagwuuzlde, göö?', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Tätest du mir einen Tschick wutzeln? - Es geht ja nichts über eine Selbergewutzelte, gelt?', '[{"kategorie": "wörtlich", "text": "\"Würdest du mir eine Zigarette drehen? - Es geht ja nichts über eine Handgedrehte, nicht wahr?\"  2. Würdest du mir eine rollen? – Selbstgedreht ist einfach ehrlicher Tabakgenuss, das sag ich dir!  3. Drehst du mir einen Tschick? – Die Selbstgedrehten sind halt einfach die Besten, oder?"}]'::jsonb, ''),
  ('daedst-ma-a-genussschdangal-wuuzln-es-geed-hoid-nix-iwa-a-soeoewagwuuzlds-hiadl-goeoe', 'Dädst ma a Genussschdangal wuuzln? - Es geed hoid nix iwa a sööwagwuuzlds Hiadl, göö?', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Tätest du mir ein Genussstangerl wutzeln? - Es geht halt nichts über ein selbergewutzeltes Hütchen, gelt?', '[{"kategorie": "wörtlich", "text": "\"Würdest du mir ''ne Genussstange drehen? - Es geht ja nichts über ''nen handgedrehten Joint, oder?\"  2. Würdest du mir einen Joint rollen? – Selbstgedreht ist einfach ehrlicher Genuss, das sag ich dir!  3. Drehst du mir einen Joint? – Die Selbstgedrehten sind halt einfach die Besten, meinst du nicht auch?"}]'::jsonb, ''),
  ('bei-uns-dahaam-wean-de-nuudln-noo-von-haund-gwuuzld', 'Bei uns dahaam wean de Nuudln noo von haund gwuuzld!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Bei uns daheim werden die Nudeln noch von Hand gewutzelt!', '[{"kategorie": "wörtlich", "text": "\"Bei uns zu Hause werden die Nudeln noch per Hand gerollt!\"  2. Bei uns daheim rollen wir die Nudeln noch von Hand – so wie sich''s gehört!  3. Bei uns kommen keine fertigen Nudeln auf den Tisch – wir rollen sie noch selber von Hand!"}]'::jsonb, ''),
  ('gee-ma-a-runde-wuuzln-owa-desmoi-zoeoen-eigntiarln-doppaed', 'Gee ma a Runde wuuzln - owa desmoi zöön Eigntiarln doppäd!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Gehen wir eine Runde wutzeln - aber diesmal zählen Eigentore doppelt!', '[{"kategorie": "wörtlich", "text": "\"Spielen wir eine Runde Tischfußball – aber dieses Mal zählt jedes Eigentor doppelt, verstanden?\"  2. Machen wir eine Session am Tischkicker – diesmal aber zählt jedes Eigentor doppelt, Deal?  3. Ich fordere dich zu einem Tischfußballmatch mit Extra-Kick - Eigentore zählen doppelt, okay?"}]'::jsonb, ''),
  ('glei-noochn-zuagriff-haums-mi-gwuuzld-jeedn-aanzlnan-finga', 'Glei noochn Zuagriff haums mi gwuuzld - jeedn aanzlnan Finga!', '', '', '', 'Wiener Gaunersprache', 'Gleich nach dem Zugriff haben sie mich gewutzelt - jeden einzelnen Finger!', '[{"kategorie": "wörtlich", "text": "\"Gleich nach der Festnahme haben sie mir die Fingerabdrücke abgenommen - jeder Finger wurde einzeln gewuzelt!\"  2. \"Gleich nach dem Zugriff haben sie mich durchgewuzelt wie beim Passamt - jeden einzelnen Finger!\"  3. Gleich nach der Festnahme haben sie mir jeden einzelnen Finger zuerst in die Stempelfarbe und dann auf ein Blatt Papier gedrückt - Reste von der Schmiere habe ich noch immer an den Pfoten!"}]'::jsonb, ''),
  ('aum-wuuzla-gibds-kaa-freindschofd', 'Aum Wuuzla gibds kaa Freindschofd!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Am Wuzler gibt es keine Freundschaft!', '[{"kategorie": "wörtlich", "text": "\"Am Drehfußballtisch gibt es keine Freundschaft!\"  2. Am Tischkicker gibt''s keine Gnade – bis die Kugel fällt!  3. Am Wuzlertisch regiert der Wettkampf, nicht die Freundschaft!"}]'::jsonb, ''),
  ('an-wuuzla-mochn', 'an Wuuzla mochn', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'einen Wuzler machen', '[{"kategorie": "wörtlich", "text": "\"eine Partie Tischfußball spielen\""}, {"kategorie": "", "text": "\"eine Session am Tischkicker machen\""}, {"kategorie": "", "text": "\"eine Partie Drehfußball spielen\""}]'::jsonb, 'Moch ma an Wuuzla? - Wea valiad, wiad lajf auf Insta expoosd!'),
  ('moch-ma-an-wuuzla-wea-valiad-wiad-lajf-auf-insta-expoosd', 'Moch ma an Wuuzla? - Wea valiad, wiad lajf auf Insta expoosd!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Machen wir einen Wutzler? - Wer verliert, wird live auf Insta exposed!', '[{"kategorie": "wörtlich", "text": "\"Spielen wir eine Runde Tischfußball? - Wer verliert, wird life auf Insta exposed!\"  2. Machen wir eine Session am Tischkicker? - Wer verliert, wird Insta-gedemütigt mit Tag & Screenshot!  3. Wie wär''s mit einer Wuzelrunde? Der Verlierer wird auf Instagram live vor allen bloßgestellt!"}]'::jsonb, 'an Wuuzla mochn'),
  ('dea-is-a-jass-von-an-wuuzla-kaana-hod-so-schnoelle-haend', 'Dea is a Jass von an Wuuzla - kaana hod so schnölle Händ!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Der ist ein Jass von einem Wuzler - keiner hat so schnelle Hände!', '[{"kategorie": "wörtlich", "text": "\"Der ist ein echtes Ass am Kickertisch – keiner hat so flinke Hände wie er!\"  2. Der ist ein Profi-Wuzler - er spielt Tischfußball auf einem ganz anderen Level!  3. Er ist ein Meister des Tischfußballs – schnell, präzise, unberechenbar und blitzschnell an den Stangen!"}]'::jsonb, ''),
  ('ea-hod-an-wuuzla-ausn-haundgelenk-zimmad-dea-ned-zum-hoidn-woa', 'Ea hod an Wuuzla ausn Haundgelenk zimmad, dea ned zum Hoidn woa!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Er hat einen Wuzler aus dem Handgelenk gezimmert, der nicht zu halten war!', '[{"kategorie": "wörtlich, Handballerjargon", "text": "\"Er hat einen Effetwurf perfekt aus dem Handgelenk rausgezwirbelt – für den Tormann unhaltbar!\"  2. Ein Dreher wie aus dem Nichts – reingeschraubt ins kurze Eck!  3. Ein feiner Spin-Wurf, der sich genau zwischen Goalie und Pfosten ins Tor gezwirbelt hat!"}]'::jsonb, ''),
  ('de-wuuzla-do-kaunnsd-glei-vagessn-kaa-profueue-mea-komplett-duach', 'De Wuuzla do kaunnsd glei vagessn - kaa Profüü mea, komplett duach!', '', '', '', 'Wiener Mechaniker-Slang', 'Die Wuzler da kannst gleich vergessen – kein Profil mehr, komplett durch!', '[{"kategorie": "wörtlich", "text": "\"Die Reifen da kannst du gleich vergessen - die haben kein Profil mehr und sind komplett abgefahren!\"  2. Mit den Schlapfen brauchst nirgends mehr hinfahren – die sind tot!  3. Die Hammerln sind so glatt, die gehören ins Ballett, nicht auf die Straße!"}]'::jsonb, ''),
  ('de-hammaln-do-san-so-glott-de-ghean-ins-ballett-und-ned-aufd-schdrossn', 'De Hammaln do san so glott - de ghean ins Ballett und ned aufd Schdrossn!', '', '', '', 'Wiener Mechaniker-Slang', 'Die Hammerln da sind so glatt - die gehören ins Ballett und nicht auf die Straße!', '[{"kategorie": "wörtlich", "text": "\"Deine Reifen da kannst gleich vergessen - die haben kein Profil mehr und sind komplett abgefahren!\"  2. Mit den Schlapfen da brauchst nirgends mehr hinfahren – die sind tot!  3. Die Wuzler da kannst gleich vergessen – kein Profil mehr, komplett durch!"}]'::jsonb, ''),
  ('i-kenn-kaan-bessan-wuuzla-oisn-hannes-fueueta-taabak-blaadl-zack-fertig-is-da-tschik', 'I kenn kaan bessan Wuuzla oisn Hannes: Füüta, Taabak, Blaadl, zack - fertig is da Tschik!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Ich kenne keinen besseren Wutzler als den Hannes: Filter, Tabak, Blättchen, zack - fertig ist der Tschick!', '[{"kategorie": "wörtlich", "text": "\"Der Hannes is der König der Wuzler: Filter, Tabak, Blättchen, zack – in 10 Sekunden hast ''nen perfekten, selbstgerollten Tschick in der Hand!\"  2. Wenn einer wuzeln kann, dann der Hannes – der braucht keine Maschine, der hat Gefühl!  3. Niemand dreht ''ne Zigarette so schnell und sauber wie der Hannes – ein echter Profi unter den Wuzlern!"}]'::jsonb, ''),
  ('si-wuuzln', 'si wuuzln', '', '', '', 'Grundwortschatz Wienerisch', 'sich wuzeln', '[{"kategorie": "wörtlich", "text": "\"sich wutzeln\" (lautmalerisches Wort, das die Bewegung/das Geräusch von etwas Kleinem, Rundem nachahmt, das sich dreht, knüllt, kringelt, rollt oder verwurstelt)"}, {"kategorie": "allg.", "text": "sich drängeln, sich winden, sich zwängen, sich wälzen, sich schlängeln"}]'::jsonb, 'Ea hod si duach de enge Wiadshaustia frech bis gaunz viire gwuuzld - und schdeed jetztd direkt aun da Bar!'),
  ('ea-hod-si-duach-de-enge-wiadshaustia-frech-bis-gaunz-viire-gwuuzld-und-schdeed-jetztd-direkt-aun-da-bar', 'Ea hod si duach de enge Wiadshaustia frech bis gaunz viire gwuuzld - und schdeed jetztd direkt aun da Bar!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Er hat sich durch die enge Wirtshaustüre frech bis ganz nach vorne gewutzelt - und steht jetzt direkt an der Bar!', '[{"kategorie": "wörtlich", "text": "\"Er hat sich durch die enge Türe frech ins Wirtshaus bis ganz nach vorne gedrängt - und steht jetzt direkt an der Schank!\"   2. Er hat sich durch die enge Wirtshaustür frech bis ganz nach vorne geschoben – und jetzt steht er direkt an der Theke!  3. Der hat sich durch die enge Wirtshaustür gewunden wie beim Limbo – und steht jetzt ganz vorn beim Zapfhahn!"}]'::jsonb, 'si wuuzln'),
  ('si-im-schnaeae-wuuzln-is-a-echte-hetz', 'Si im Schnää wuuzln is a echte Hetz!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Sich im Schnee zu wutzeln, ist ''ne echte Hetz!', '[{"kategorie": "wörtlich", "text": "\"Sich im Schnee zu wälzen ist eine Mordsgaudi!\"  2. Im Schnee herumzurollen wie ein Ratrac macht so richtig Spaß!  3. Sich im Schnee zu wuzeln ist wie ein Schneebad für die Seele!"}]'::jsonb, ''),
  ('wos-hostn-mit-dein-heemad-gmochd-des-is-jo-voi-dawuuzld', 'Wos hostn mit dein Heemad gmochd? - Des is jo voi dawuuzld!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Was hast du denn mit deinem Hemd gemacht? - Das ist ja voll derwutzelt!', '[{"kategorie": "wörtlich", "text": "\"Was hast denn du mit deinem Hemd angestellt? Das is ja komplett zerknittert!\"  2. Dein Hemd ist ja komplett zerknautscht - hast du etwa darin geschlafen?  3. Das Hemd musst du direkt aus dem Wäschekorb genommen haben - so zerknüllt wie es aussieht!"}]'::jsonb, ''),
  ('da-witz-woa-so-deppad-i-hob-mi-fost-dawuuzld-vua-lochn', 'Da Witz woa so deppad - I hob mi fost dawuuzld vua Lochn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der Witz war so deppert - ich hab mich fast derwutzelt vor Lachen!', '[{"kategorie": "wörtlich", "text": "\"Der Schmäh war so blöd – ich hab mich fast zerkugelt vor Lachen!\"  2. Der Witz war so bescheuert – ich hab mich fast weggeschmissen vor Lachen!  3. Der Gag war so gaga - ich hab mich fast zerlegt vor Lachen!"}]'::jsonb, 'si dawuuzln'),
  ('si-dawuuzln', 'si dawuuzln', '', '', '', 'Grundwortschatz Wienerisch', 'sich derwuzeln', '[{"kategorie": "wörtlich", "text": "\"sich derwutzeln\" (aus dem intensivierenden Präfix [[der-]]=\"zer-\" und \"wutzeln\"=\"knittern\")"}, {"kategorie": "scherzhaft für", "text": "\"sich kaputtlachen\", \"sich krümmen vor Lachen\", \"sich kaum noch einkriegen vor Lachen\", \"sich krumm und bucklig lachen\", sich kringeln vor Lachen, [[sich]] abbröseln, [[sich]] abhauen, [[sich]] abpecken, [[sich]] einen Ast lachen, [[sich]] zerbären, [[sich]] zerfransen, [[sich]] zernegern, [[sich]] zerpecken, [[sich]] zerscheppern [[sich zerkugeln]]"}]'::jsonb, 'Da Witz woa so deppad - I hob mi fost dawuuzld vua Lochn!'),
  ('si-duachwuuzln', 'si duachwuuzln', '', '', '', 'Grundwortschatz Wienerisch', 'sich durchwuzeln', '[{"kategorie": "wörtlich", "text": "\"sich durchwutzeln\" (aus dem Partikel \"durch\"=\"hindurch\" und \"wutzeln\"=\"zwängen\")"}, {"kategorie": "allg.", "text": "sich durchzwängen, sich durchwinden, sich durchwurschteln, sich durchschlängeln"}]'::jsonb, 'Zua Gaadroob muassd di easchd bis gaunz viire duachwuuzln!'),
  ('zua-gaadroob-muassd-di-easchd-bis-gaunz-viire-duachwuuzln', 'Zua Gaadroob muassd di easchd bis gaunz viire duachwuuzln!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Zur Garderobe musst du dich erst bis ganz nach vorne durchwutzeln!', '[{"kategorie": "wörtlich", "text": "\"Zur Garderobe musst du dich erst bis ganz nach vorne durchzwängen!\"  2. Wenn du zur Garderobe willst, musst du dich erst durch die Menschenmasse bis ganz nach vorne durchwurschteln!  3. Bis zur Garderobe musst du dich erst wie ein Aal durch die Menge bis ganz nach vorne schlängeln!"}]'::jsonb, 'si duachwuuzln'),
  ('noochn-aufschdee-schau-i-aus-wia-zwuuzld', 'Noochn Aufschdee schau I aus wia zwuuzld!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Nach dem Aufstehen sehe ich aus wie zerwutzelt!', '[{"kategorie": "wörtlich", "text": "\"Nach dem Aufstehen sehe ich total zerknautscht aus!\"  2. Nach dem Aufstehen sehe ich völlig zerknittert und verwurschtelt aus!  3. Nach dem Aufstehen sehe ich aus, als hätte mich jemand durch den Fleischwolf gedreht!"}]'::jsonb, ''),
  ('nooch-da-numma-gestan-nocht-woa-de-bettwaesch-so-zawuuzld-ois-haeaedn-fuemf-leid-drin-grangld', 'Nooch da Numma gestan Nocht woa de Bettwäsch so zawuuzld, ois häädn fümf Leid drin grangld!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Nach der Nummer gestern Nacht war die Bettwäsche zerwutzelt, als hätten fünf Leute darin gerangelt!', '[{"kategorie": "wörtlich", "text": "\"Nach der Nummer gestern Nacht war die Bettwäsche so zerknittert, als hätten fünf Leute darin gerangelt!\"  2. Nach dem One-Night-Stand letzte Nacht war die Bettwäsche so zerknautscht, als hätte drinnen ein Wrestling-Wettkampf stattgefunden!  3. Nach der Action letzte Nacht war die Bettwäsche so verwurschtelt, als hätten sich fünf Affen darin geprügelt – und nicht gekuschelt!"}]'::jsonb, ''),
  ('si-zwuuzln', 'si zwuuzln', '', '', '', 'Grundwortschatz Wienerisch', 'sich zerwuzeln', '[{"kategorie": "wörtlich", "text": "\"sich zerwutzeln\" (von [[wutzeln]] = lautmalerisches Wort, das die Bewegung/das Geräusch von etwas Kleinem, Rundem nachahmt, das sich dreht, knüllt, kringelt, rollt oder verwurstelt)"}, {"kategorie": "allg.", "text": "\"sich kaputtlachen\", \"sich krumm und bucklig lachen\", sich kringeln vor Lachen, \"sich kaum noch einkriegen vor Lachen\", [[sich]] abbröseln, [[sich]] abhauen, [[sich]] abpecken, [[sich]] einen Ast lachen, [[sich]] zerbären, [[sich]] zerfransen, [[sich]] zernegern, [[sich]] zerpecken, [[sich]] zerscheppern"}]'::jsonb, 'I hob mi sowos von zwuuzld - mei Bauchnoowä hod Applaus klotschd!'),
  ('i-hob-mi-sowos-von-zwuuzld-mei-bauchnoowae-hod-applaus-klotschd', 'I hob mi sowos von zwuuzld - mei Bauchnoowä hod Applaus klotschd!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Ich hab mich sowas von zerwutzelt - mein Bauchnabel hat Applaus geklatscht!', '[{"kategorie": "wörtlich", "text": "\"Ich hab mich so kaputtgelacht, dass ich rund um den Bauchnabel ''nen Krampf gekriegt hab!\"  2. Ich hab mich dermaßen totgelacht, dass ich mir hinterher den Bauch halten musste!  3. Ich hab mich derart weggeschmissen vor Lachen, dass mein Nabel gezittert hat wie ein Wackelpudding!"}]'::jsonb, 'si zwuuzln'),
  ('si-zawuuzln', 'si zawuuzln', '', '', '', 'Grundwortschatz Wienerisch', 'sich zerwuzeln', '[{"kategorie": "wörtlich", "text": "\"sich zerwutzeln\" (von [[wutzeln]] = lautmalerisches Wort, das die Bewegung/das Geräusch von etwas Kleinem, Rundem nachahmt, das sich dreht, knüllt, kringelt, rollt oder verwurstelt)"}, {"kategorie": "allg.", "text": "\"sich kaputtlachen\", \"sich krumm und bucklig lachen\", sich kringeln vor Lachen, \"sich kaum noch einkriegen vor Lachen\", [[sich]] abbröseln, [[sich]] abhauen, [[sich]] abpecken, [[sich]] einen Ast lachen, [[sich]] zerbären, [[sich]] zerfransen, [[sich]] zernegern, [[sich]] zerpecken, [[sich]] zerscheppern"}]'::jsonb, 'I hob mi deamaassn zawuuzld, dass ma beim Lochn a Schaas nochn aundan duach de Hoosn gflutschd is!'),
  ('i-hob-mi-deamaassn-zawuuzld-dass-ma-beim-lochn-a-schaas-nochn-aundan-duach-de-hoosn-gflutschd-is', 'I hob mi deamaassn zawuuzld, dass ma beim Lochn a Schaas nochn aundan duach de Hoosn gflutschd is!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Ich hab mich dermaßen zerwutzelt, dass mir beim Lachen ein Schas nach dem anderen durch die Hose geflutscht ist!', '[{"kategorie": "wörtlich", "text": "\"Ich hab mich dermaßen kaputtgelacht, dass mir ein Furz nach dem anderen aus dem Arsch gepfiffen ist!\"  2. Ich hab mich krumm und bucklig gelacht, bis meine Pobacken gebrannt haben!  3. Ich hab mich derart weggeschmissen vor Lachen, dass mein Hinterteil Schnappatmung bekam!"}]'::jsonb, 'si zawuuzln'),
  ('a-gwuuzlde', 'a Gwuuzlde', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'eine Gewuzelte', '[{"kategorie": "wörtlich", "text": "\"eine Gewutzelte\" (von [[wutzeln]] = lautmalerisches Wort, das die Bewegung/das Geräusch von etwas Kleinem, Rundem nachahmt, das sich dreht, knüllt, kringelt, rollt oder verwurstelt)"}, {"kategorie": "allg., Tabak", "text": "\"eine Gedrehte\", \"eine selbst gedrehte Zigarette\", \"eine handgemachte Zigarette\", \"eine selbstgedrehte Zigarette von Hand\", [[Sööwagwuuzlde]], [[Span]], [[Tschick]], [[Genussstangerl]]"}, {"kategorie": "Cannabis", "text": "\"ein selbst gedrehter Joint\", \"ein handgemachter Joint\", \"ein selbstgedrehter Joint von Hand\", [[Sööwagwuuzlda]], [[Genussstangerl]], [[Hiadl]], [[Ofen]], [[Diiwä]], [[Sepperl]], [[Gerät]]"}]'::jsonb, 'Tschüü amoi - I draa uns dawäu a frisch Gwuuzlde von Haund!'),
  ('de-foaschein-woa-so-vawuuzld-dass-eam-da-automaat-nimma-gnumma-hod', 'De Foaschein woa so vawuuzld, dass eam da Automaat nimma gnumma hod!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der Fahrschein war so verwutzelt, dass ihn der Automat nicht mehr genommen hat!', '[{"kategorie": "wörtlich", "text": "\"Der Fahrschein war so verknüllt, dass ihn der Automat gleich wieder ausgespuckt hat!\"  2. Mein Ticket war so verrubbelt, dass der Automat das Ding nicht mal erkannt hat!  3. Die Fahrkarte war dermaßen verknittert, dass der Automat sie nicht fressen wollte!"}]'::jsonb, ''),
  ('i-hob-de-easchde-seitn-von-mein-roman-zum-xtn-moi-zsaummgwuuzld-und-in-mistkiiwaeae-ghaud-scheiss-schreibkraumpf', 'I hob de easchde Seitn von mein Roman zum -xtn Moi zsaummgwuuzld und in Mistkiiwää ghaud - scheiss Schreibkraumpf!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Ich hab die erste Seite von meinem Roman zum x-ten Mal zusammengewutzelt und in den Mistkübel gehaut!', '[{"kategorie": "wörtlich", "text": "\"Ich hab die erste Seite meiens Romans zum hundertsten Mal zusammengeknüllt und in den Mistkorb geworfen – verfluchter Schreibkrampf!\"  2. Die erste Seite meines Romans liegt zum hundertsten Mal zusammengeknüllt im Mülleimer – dieser verdammte Anfangsteufel!  3. Ich hab Seite eins wieder mal zu einer Papierkugel zusammengeknüllt – direkt im Mistkorb gelandet, wie ihre 37 Vorgänger!"}]'::jsonb, ''),
