  ('mit-schmuudln-und-schmiian-hodas-bis-zum-oowaschdrizzi-brochd', 'Mit Schmuudln und Schmiian hodas bis zum Oowaschdrizzi brochd!', '', '', '', 'Wiener Gaunersprache', 'Mit Schmudeln und Schmieren hat er es bis zum Oberstrizzi gebracht!', '[{"kategorie": "wörtlich", "text": "\"Mit Schöntuerei und Schmieren hat er es bis zum großen Onkel gebracht!\"  2. Mit Einschleimen und Schmieren hat er es bis zum Oberbonzen geschafft!  3. Mit Anbiederei und Schmieren ist er bis zum Oberboss aufgestiegen!"}]'::jsonb, ''),
  ('des-maadl-hod-den-schmuus-von-eam-echt-glaubd-dabei-hodas-von-aufaung-au-betroong', 'Des Maadl hod den Schmuus von eam echt glaubd - dabei hodas von Aufaung au betroong!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Das Mädel hat den Schmus von ihm echt geglaubt - dabei hat er sie von Anfang an betrogen!', '[{"kategorie": "wörtlich", "text": "\"Das Mädel ist auf sein süßes Geschwafel reingefallen – dabei war von Anfang an alles gelogen!\"  2. Das Mädel hat seinen Schleim echt geglaubt – dabei war sie nur ein Spielball für ihn!  3. Die Kleine hat sich von seiner Schöntuerei einlullen lassen – dabei hat er sie die ganze Zeit nur verarscht!"}]'::jsonb, ''),
  ('dazoeoe-kaan-schmuus', 'Dazöö kaan Schmuus!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Erzähle keinen Schmus!', '[{"kategorie": "wörtlich", "text": "\"Erzähl keinen Stuss!\"  2. Red keinen Unsinn!  3. Hör auf mit dem Geschwafel!  4. [[Dazöö]] kane Schmää!"}]'::jsonb, 'Dazöö kaane Schmää!'),
  ('ob-zwaa-promueue-wiada-zum-schmusarantn-und-schmuudld-jeede-koeoenarin-von-oobm-bis-untn-oo', 'Ob zwaa Promüü wiada zum Schmusarantn und schmuudld jeede Köönarin von oobm bis untn oo!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Ab zwei Promille wird er zum Schmuseranten und schmudelt jede Kellnerin von oben bis unten ab!', '[{"kategorie": "wörtlich", "text": "\"Ab zwei Promille wird er zum Schmusetiger und knuddelt jede Kellnerin ab!\"  2. Sobald er einen sitzen hat, wird er zudringlich und busselt jede Kellnerin von Kopf bis Fuß ab!  3. Im Rausch wird er zum Schmusetiger und knutscht jede Kellnerin von oben bis unten ab!"}]'::jsonb, ''),
  ('des-is-ka-mochatschek-des-is-a-schmusarant-glaub-eam-kaa-wuat', 'Des is ka Mochatschek, des is a Schmusarant - glaub eam kaa Wuat!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Das ist kein Machatschek, das ist ein Schmuserant - glaub ihm kein Wort!', '[{"kategorie": "wörtlich", "text": "\"Das ist kein Macher, das ist ein Schwätzer - glaub ihm kein Wort!\"  2. Das ist kein Macher, das ist ein Phrasendrescher - den darfst du nicht ernst nehmen!  3. Der ist kein Macher-Typ, sondern ein Schwafler – da ist nichts dahinter!"}]'::jsonb, ''),
  ('de-zwaa-iwawuuzldn-schmuusn-mitanaund-ois-waradns-easchd-zwanzg', 'De zwaa Iwawuuzldn schmuusn mitanaund, ois waradns easchd zwanzg!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Die zwei Überwuzelten schmusen miteinander, als wären sie erst 20!', '[{"kategorie": "wörtlich", "text": "\"Die zwei Überreifen schmusen miteinander, als wären sie erst 20!\"  2. Die zwei alten Knacker knutschen herum, als wären sie noch Teenager!  3. Die beiden Grauköpfe turteln rum, als wären sie gerade in der Pubertät!"}]'::jsonb, ''),
  ('schmuus-kaan-schaas-sog-endlich-de-woaheit', 'Schmuus kaan Schaas - sog endlich de Woaheit!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Schmus'' keinen Schas - sag endlich die Wahrheit!', '[{"kategorie": "wörtlich", "text": "\"Red keinen Quatsch - sag endlich die Wahrheit!\"  2. Erzähl'' keinen Stuss - sag endlich, was wirklich wahr!  3. Hör auf mit dem Geschwafel – es ist höchste Zeit für d''Wahrheit!"}]'::jsonb, ''),
  ('hea-ooba-des-fleisch-aum-toella-is-wuuziklaa-hob-i-leichd-a-kindaschnitzl-beschdoeoed', 'Hea Ooba, des Fleisch aum Tölla is wuuziklaa - hob I leichd a Kindaschnitzl beschdööd?', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Herr Ober, das Fleisch am Teller ist wutziklein - hab ich vielleicht ein Kinderschnitzel bestellt?', '[{"kategorie": "wörtlich", "text": "\"Herr Ober, was soll ich mit dem klitzekleinen Fleischstück auf meinem Teller - hab ich etwa ein Kinderschnitzel bestellt?\"  2. So klitzeklein und darf schon allein aus der Küche - da hätt ich ja gleich einen Kinderteller bestellen können!  3. Herr Ober, Sie haben sich im Tisch geirrt - ich hab kein klitzekleines Kinderschnitzel bestellt!"}]'::jsonb, '')
